using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Reflection;using System.Text;using System.Text.RegularExpressions;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Threading.Tasks;
static class V131Checks{
static void Check(bool ok,string text,List<string> log,string path){log.Add((ok?"PASS ":"FAIL ")+text);if(!ok||log.Count%100==0)File.WriteAllLines(path,log.ToArray(),Encoding.UTF8);if(!ok)throw new Exception(text);}
public static void Run(string path,bool onlyNew=false){Engine.DataRoot=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)),"state-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Engine.DataRoot);var log=new List<string>();try{var bank=Bank.All();Check(bank.Count==150&&bank.Select(p=>p.Number).SequenceEqual(Enumerable.Range(1,150))&&bank.Select(p=>p.Id).Distinct().Count()==150,"150 consecutive display numbers and unique stable storage IDs",log,path);Check(bank.Where(p=>p.Id<=90).Select(p=>p.Id).OrderBy(id=>id).SequenceEqual(Enumerable.Range(1,90)),"Existing 90 IDs retained; new ordinary IDs do not overlap dark levels",log,path);Check(bank.Select(p=>p.Id).SequenceEqual(PracticeOrder.Ids)&&bank.Skip(147).Select(p=>p.Id).SequenceEqual(new[]{88,89,90}),"Difficulty progression ends with three comprehensive projects",log,path);Check(PracticeKnowledge.All.All(l=>l.New.Concat(l.Review).All(t=>Problem.NumberOf(t.FirstProblem)<=l.Problem.Number)),"Knowledge first appearances follow new difficulty order",log,path);Check(bank.Count(p=>Regex.Matches(p.Reference,@"#include").Count==1&&p.Reference.Contains("<stdio.h>"))==149,"149 of 150 references use stdio.h alone; linked-list allocation lesson retains stdlib.h",log,path);Check(PracticeKnowledge.All.Count==150&&PracticeKnowledge.All.All(p=>p.Goal.Length>6),"All 150 knowledge lessons available",log,path);
AppSettings.SetLanguage("en");foreach(var p in bank){foreach(var text in new[]{p.Title,p.Category,p.Statement,p.Hint,PracticeKnowledge.For(p.Id).Goal})Check(!Regex.IsMatch(L.T(text),@"[\u4e00-\u9fff]"),"English content "+p.Number,log,path);}AppSettings.SetLanguage("zh");
var before=Assembly.LoadFrom(Path.GetFullPath(Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location),"../ver1.3/Feng_C语言练习器_ver1.3.exe")));var levels=(System.Collections.IEnumerable)before.GetType("ChallengeBank").GetField("Levels").GetValue(null);int index=0;foreach(object old in levels){var current=ChallengeBank.Levels[index++];var type=old.GetType();foreach(string name in new[]{"Number","Seconds","Learning"})Check(object.Equals(Value(old,name),Value(current,name)),"Dark level "+index+" unchanged "+name,log,path);object problem=type.GetField("Problem").GetValue(old);foreach(string name in new[]{"Id","Title","Category","Statement","Hint","Reference"})Check(object.Equals(problem.GetType().GetField(name).GetValue(problem),current.Problem.GetType().GetField(name).GetValue(current.Problem)),"Dark problem "+index+" unchanged "+name,log,path);}
int total=0;foreach(var p in onlyNew?bank.Where(p=>NewBank.IsNew(p.Id)):bank.Concat(ChallengeBank.Levels.Select(l=>l.Problem))){foreach(int seed in !onlyNew&&NewBank.IsNew(p.Id)?new[]{20261102,424242}:new[]{20261102}){var ev=Engine.Judge(p,p.Reference,seed,CancellationToken.None,(a,b)=>{});if(!ev.Compiled||ev.Cases.Any(c=>!c.Passed)){File.WriteAllText(path+"-failure-"+p.Id+".txt",Engine.Report(ev),Encoding.UTF8);}Check(ev.Compiled&&ev.Cases.Count==28&&ev.Cases.All(c=>c.Passed)&&ev.Score>=99.9,"Judge "+p.Id+" seed "+seed+" score "+ev.Score,log,path);total+=ev.Cases.Count;}}
Check(total==(onlyNew?1680:7280),"Cases passed: "+total,log,path);Check(!Engine.Match("000","0",out dummy,true)&&NewBank.IsText(213),"Leading-zero identifiers compared as text",log,path);log.Add("ALL VER1.3.1 CHECKS PASSED");}catch(Exception e){log.Add("FAIL "+e);Environment.ExitCode=1;}File.WriteAllLines(path,log.ToArray(),Encoding.UTF8);}
static object Value(object o,string n){var t=o.GetType();var f=t.GetField(n);return f!=null?f.GetValue(o):t.GetProperty(n).GetValue(o,null);}
static string dummy;static T F<T>(object o,string n){return(T)o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}
public static void UI(Application app,string path){Engine.DataRoot=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)),"ui-state-"+Guid.NewGuid().ToString("N"));AppSettings.Load();GlassTheme.Apply(false,false);var log=new List<string>();var w=new MainWindow(true);w.ContentRendered+=async(s,e)=>{try{await Transitions.WhenReady(w);var list=F<ListBox>(w,"list");Check(list.Items.Count==150,"Sidebar contains all 150 questions",log,path);foreach(int id in new[]{1,90,201,245,246,256,260}){list.SelectedItem=list.Items.Cast<ListBoxItem>().First(x=>((Problem)x.Tag).Id==id);Check(F<TextBlock>(w,"title").Text.StartsWith(Problem.NumberOf(id).ToString("00")),"Display number "+Problem.NumberOf(id)+" selects correct problem",log,path);var k=new KnowledgeWindow((Problem)((ListBoxItem)list.SelectedItem).Tag){Owner=w};k.Show();await Transitions.WhenReady(k);k.Close();await Task.Delay(220);}
var search=F<TextBox>(w,"search");search.Text="150";Check(list.Items.Count==1&&((Problem)((ListBoxItem)list.Items[0]).Tag).Id==90,"Search 150 routes to final project",log,path);search.Text="";var ed=F<CodeEditor>(w,"editor");ed.Text="int main(void) {\n    int amount = 10;\n    return amount;\n}\n";int hits=0;foreach(string lang in new[]{"zh","en"})foreach(int ui in new[]{13,16})foreach(double dpi in new[]{96.0,144.0,192.0}){AppSettings.SetLanguage(lang);AppSettings.SetInterfaceFont(ui);w.PreviewSize(2560*96/dpi,1600*96/dpi);foreach(int font in AppSettings.FontSizes){AppSettings.SetFont(font);w.UpdateLayout();ed.RefreshView();ed.Input.ScrollToHome();for(int i=0;i<ed.Text.Length-1;i++){if(ed.Text[i]=='\n'||ed.Text[i+1]=='\n')continue;var a=ed.Input.CharacterRect(i);var b=ed.Input.CharacterRect(i+1);if(b.X<=a.X)continue;Check(ed.Input.Hit(new Point(a.X+(b.X-a.X)*.2,a.Y+a.Height*.5))==i,"Hit "+(++hits),log,path);}}Check(ed.ActualHeight>=120,"Editor remains usable at "+dpi+" dpi / UI "+ui,log,path);}
AppSettings.SetInterfaceFont(13);AppSettings.SetFont(16);AppSettings.SetLanguage("zh");w.PreviewSize(1600,1000);list.SelectedItem=list.Items.Cast<ListBoxItem>().First(x=>((Problem)x.Tag).Id==260);await Task.Delay(120);Theme.Capture((FrameworkElement)w.Content,Path.Combine(Path.GetDirectoryName(path),"main-150-zh.png"),153.6);AppSettings.SetLanguage("en");await Task.Delay(120);Theme.Capture((FrameworkElement)w.Content,Path.Combine(Path.GetDirectoryName(path),"main-150-en.png"),153.6);log.Add("ALL VER1.3.1 UI CHECKS PASSED / hits="+hits);File.WriteAllLines(path,log.ToArray(),Encoding.UTF8);w.Close();}catch(Exception ex){log.Add("FAIL "+ex);File.WriteAllLines(path,log.ToArray(),Encoding.UTF8);app.Shutdown(1);}};app.Run(w);}
}
